import { api, type Page } from "@/lib/apiClient";
import type { Vendor } from "@/modules/procurement/types";

export function listVendors(params: { limit?: number; status?: string } = {}): Promise<Page<Vendor>> {
  return api.get<Page<Vendor>>("/procurement/vendors", { params });
}
import { useQuery } from "@tanstack/react-query";

import { listVendors } from "@/modules/procurement/api";

/** All active vendors for a picker (a plain select, not paginated — mirrors
 * finance's useAccountOptions; a searchable combobox is worth adding once a
 * vendor list outgrows one page). */
export function useVendorOptions() {
  return useQuery({
    queryKey: ["procurement", "vendors", "options"],
    queryFn: () => listVendors({ status: "ACTIVE", limit: 200 }),
    staleTime: 60_000,
  });
}
/**
 * Mirrors backend `app/modules/procurement/schemas/vendors.py` (STRUCTURE §4). Only the
 * slice the finance AP workbench needs (a vendor picker) — the full procurement module
 * lands in PLAN 15.6.
 */

export type VendorStatus = "ACTIVE" | "INACTIVE";

export interface Vendor {
  id: string;
  vendor_code: string;
  name: string;
  status: VendorStatus;
  default_currency_code: string;
  payment_terms_days: number;
  tax_reference: string | null;
  email: string | null;
  phone: string | null;
  address: string | null;
  notes: string | null;
  created_at: string;
}

